namespace CampaignCreator;

internal sealed record GuideTopic(string Id, string Title, string Changes, string Saves, string Game, string Limits, string[] Related)
{
    public override string ToString() => Title;
    internal string SearchText => string.Join(" ", Title, Changes, Saves, Game, Limits,
        string.Join(" ", StudioGuideReference.For(Id).Select(e => e.Label + " " + e.Description)));
}

internal static class StudioGuideContent
{
    internal static readonly GuideTopic[] Topics =
    [
        new("start", "Start here · content and workflow",
            "Every launch begins with the beta notice before Home or startup tasks. Some features may be broken or behave differently from their descriptions; its Discord and GitHub links help you report problems. Choose I understand · Open Studio to continue, or Exit to close. Studio then checks GitHub for updates, including betas, and asks before downloading and running a newer Studio and mod installer. Check for updates on Home retries this. Save edits and close Tape to Tape before installing; Studio reopens afterward. Launch Tape to Tape on Home also checks for updates and verifies mod compatibility before opening Steam. A network failure leaves the editor usable and can be retried. Home has three cards: Campaigns, Players and Teams. Pick Skater or Goalie, or Player team or Campaign opponent, then Create new, Edit existing or Import a copy of other content. The Campaigns card also has Import and Upload for sharing whole campaigns. A campaign ties together its opponents, maps, player teams, free agents and reward pools. Help (or F1) points at the controls on the current page and explains them; it never clicks, fills or saves anything. Report a bug opens a report form; Open on GitHub then prepares an issue in your browser. Nothing is submitted until you submit it there.",
            "Each editor has its own save button. Home and Back leave without saving and discard unsaved edits; only closing the Studio window asks first. Creating, importing and some asset tools write files as soon as you use them. The screens in this guide are pictures with example content and cannot change your content.",
            "Save the campaign and its teams, players and maps, select the campaign on Home, then restart Tape to Tape with the mod installed. Export to Play Now is a separate workflow. When pictures are missing or outdated, opening Studio offers Read game artwork or Later. It reads its head, logo, equipment, stadium and map pictures and the base-game rosters from your own Tape to Tape install; until it can, those previews show as unavailable. Use Read game artwork on Home to rebuild these files and, if the game cannot be found, choose its installation folder. The game doesn't need to be running, but only the game proves your content works.",
            "Flat previews show what you authored, not how it plays. A successful save or export does not check every game rule, animation, material or controller interaction.", ["campaign", "sources", "export"]),
        new("campaign", "Campaign selection, saving and game progress",
            "The campaign overview has cards for Opponents, Custom teams, Maps, Free agents and Reward pools, plus a Needs attention list when an opponent is on no map node or a node uses a team that no longer exists. Game options turns on offside for every match of the campaign, with an optional penalty: Whistle, Lose Puck or Knockout. The Home selector chooses the campaign the game loads; None (base game) turns campaigns off. A new campaign's name becomes its folder. Campaigns > Import installs a campaign zip or downloads one from the community list; if the name is taken, Keep both renames it and Replace mine moves your copy to campaign_backups first. Upload shares a saved campaign, with the logos it uses, in the public community folder; it can't be removed from Studio.",
            "Save campaign writes the campaign settings, starting choices, free agents, reward pools and maps. Save maps writes the maps on their own. A new campaign has a working draft before its first named save. The Home selector saves its choice immediately. Studio saves are separate from the game's run save.",
            "Restart the game after changing the active campaign. Continue resumes the current run; New Run resets campaign progress. Offside uses the game's own rule, forced on per match the way the Linesman talent does it, so your Advanced Settings choice is never changed; a chosen penalty is used during the run and your own is put back afterwards. Editing a campaign does not erase a run, but saved map changes apply to new runs, so test rule, roster and map changes in a new run.",
            "The game's run save, the mod's progress file and map receipts are separate files, not one save slot. Check Continue across a match and a boss transition in game.", ["maps", "squads", "sources"]),
        new("sources", "Libraries, imports and ownership",
            "Player import pickers have three tabs; team imports also have Player team library. Base game lists the game's own teams and players, read from your Tape to Tape install. In-game custom lists the custom teams and players the game has saved, made in its editor or exported from Studio; they are read from the game's save folder each time, and every copy is listed with its date. Campaign custom lists your campaigns' content and your Studio library. Import from file takes a file from anywhere. Library player teams are reusable originals: importing one into a campaign makes an independent copy, and editing the copy does not change the original.",
            "Import and creation can copy files immediately; edited fields use the destination editor's save button. Check the destination name and roster after importing. Player teams bring their roster files with them, and a copy is not linked to its source.",
            "Ordinary imports copy the editable fields; a matching name, face or outfit does not grant native player or team identity checks. Home > Copy vanilla campaign preserves native roster and opponent identities, candidate pools and unedited settings for the chosen squad. It creates a draft: name it, save it and select it on Home. Editing that copy applies the authored overrides; native event, equipment and player requirements still apply. Export to Play Now creates separate game content; after changing a Studio original, export again.",
            "A choice the Studio doesn't recognise clears to Nothing selected and may block saving. Imported relic and talent titles the Studio doesn't know stay visible as unavailable entries so nothing is lost; that does not prove the game can find them. After a game update, Studio offers to rebuild base-game lists and pictures from your installed game. Use Read game artwork on Home to retry a skipped or failed read.", ["players", "teams", "export"]),
        new("players", "Players · identity, attributes and talents",
            "Name and Number identify the player. Number style can Inherit team or use this player's own Regular, Roman numerals or Prison format; it is independent of Team equipment. Native imports preserve each player's format, so a goalie can differ from the skaters. Appearance edits the look; Details & attributes edits stats and talents. The roster slot sets Position. Skaters have size, size offset (body scale; blank is normal), handedness, speed, shot power, accuracy, checking, an ability and talents. Goalies have skill, catching, glove, blocker, five hole, standing and butterfly speed, control, recovery, pass power, shot power, poke check, depth, Pass Read and goalie talents. Pass Read uses the native 0–1 range: zero uses normal pass reaction; any positive value enables quick reading only when the current difficulty permits it, with no graded strength above zero. A superstar choice can pick which of the campaign's player teams its preview uses.",
            "Save changes writes the player once required fields are filled. Typing and choosing stay as unsaved edits until then, although a created or imported player may already exist on disk. Home and Back discard unsaved edits without asking.",
            "Campaign players are used where they are assigned: a roster, the starting choices or the free agents. A saved library player is not placed in a campaign by itself. Export to Play Now is a separate workflow.",
            "Goalies have no ability. Opponent skaters can only use abilities the AI supports. Counts as Prince for Crusader brawls qualifies only that skater for the bodycheck brawl; it grants no other Prince identity or behaviour. The opponent needs Bodycheck brawl enabled, the victim must be winding up a charged shot, and native Elite-match and challenge gates still apply. Choices come from known game data, and imported values the game may not support are flagged. Stats are not simulated in the Studio.", ["appearance", "rosters", "export"]),
        new("appearance", "Appearance · inheritance, equipment and colors",
            "Colors follow the base game: the team sets every kit color for home and away, and a player owns only their stick and skate colors (goalies: stick and blocker), one set for both kits. Team equipment on uses the team's equipment styles; off lets the player choose their own. A skater's stick style is always the player's; a goalie's stick follows the team's goalie gear unless Team equipment is off. Skates have no style. The head is a skater's own choice and some heads have no selectable helmet variant; a goalie's head is the mask. Socks can follow the jersey or use their own style, and choosing a jersey sets matching sleeves; Biceps / sleeves can override them in Premade mode. With Team equipment off and team-color jerseys home and away, a player can choose their own logo. Home/Away switch the kit you preview and, with Team equipment off, which kit styles you edit. The goalie mask is shared across both kits. Front/Back change only the preview angle.",
            "Save changes keeps a player's look; Save player team or Save opponent keeps the team's. Fill look copies equipment, colors, goalie gear and number style from a base-game, in-game custom or campaign team into the current draft; identity, logo, roster and other settings stay unchanged. A team's Home and Away values are saved separately, except the shared goalie mask. Preview facing is not saved.",
            "In game the team's kit is applied to every player, then each player's own styles (with Team equipment off) and their stick and skate colors. Export to Play Now resolves the look and adds mod data for parts the game's save format can't hold.",
            "The flat preview cannot prove 3D fit, animation, lighting or texture detail. Team colors equips the ordinary native helmet without a talent or stat bonus. None removes that ordinary starting helmet; talent, transformation and reward helmets keep their native rules. Home Helmet controls physical starting equipment; Helmet Away does not independently equip, remove or replace the physical helmet. Loss, drops and restoration use native equipment state. Selecting the native Wing style equips its matching equipment without adding a talent; native Wing drop rules apply. Other special helmet artwork requires its native equipment source. A missing preview does not mean the game lacks the piece. Premade styles are fixed artwork and ignore colors. Extra exported appearance needs the mod installed.", ["defaults", "teams", "heads", "export"]),
        new("defaults", "Default look for new players and teams",
            "Home's Set default opens the default team look: logo, home and away skater and goalie equipment, colors and number style, with Fill look and a Stick (new players) choice. New player teams and opponents start with all of it; new players start with its styles and stick. A piece left unset takes its home choice for the away kit. Until a default is saved, the Studio offers Set default or Later at startup.",
            "Save default stores the defaults and returns Home; Cancel leaves them unchanged. Existing players and teams are not rewritten. A player with no team previews in the saved default look; the built-in kit is used only when no default is saved.",
            "New content made from the defaults still needs saving and assigning or exporting. Once a player joins a team, that team's kit applies.",
            "This is not a global in-game uniform override. The default look has no Needs attention check, so review blank or unavailable choices before saving it.", ["appearance", "players"]),
        new("teams", "Teams · identity, logos and presentation",
            "Team settings holds the name, city, abbreviation, description, transition colors, goal celebration and Stat Scale. Player teams also have Injuries (On by default except Oldschool; choosing a different squad resets this default), the squad template, mascot, squad icon and Zamboni head. Team look holds the team logo, the skater and goalie equipment, colors and the number style: Regular (27), Roman numerals (XXVII) or Prison (00027). The default look has a logo too, which new teams start with. Team roster holds the players and team relics. Colour guide shows which color channel tints which part of each piece.",
            "Save player team or Save opponent writes the team and its equipment. Importing a logo can create an image file immediately; save the team to keep the choice. Goal audio is converted into the draft and embedded when the team is saved. Closing an editor does not remove files it created.",
            "Opponents play on the map nodes they are assigned to, with their own logo, if they have one, above the node. Player teams are playable custom squads. Stat Scale multiplies skater speed, shot power, accuracy and checking, and the goalie's numeric attributes except Pass Read. The team's number style applies to players set to Inherit team; explicit player styles take priority. Supported appearance, including resolved number styles, can be exported to Play Now with the mod's companion data.",
            "The flat crest preview does not verify the game's squad card or match presentation. Large custom squad lists and controller navigation need checking in game. Squad behaviors routes native gameplay checks for custom IDs on the supported game build; play testing is still needed for menu and match presentation.", ["rosters", "behaviors", "squads", "audio", "opponents"]),
        new("rosters", "Roster slots and independent player copies",
            "Team roster shows a card for each position. + New player creates a player and Import player copies one in; open a card to edit that player, and × removes one. For player teams the preset and Squad behaviors decide setup and lines. Start active chooses which authored skaters start on the ice; unchecked players start on the bench and keep their files. With a three- or four-skater limit, choose the active starters before saving. Team relics is editable. Add template starting relics copies the preset's base-team relics into it, adding only missing entries. Repeated clicks do not add duplicates; a removed relic is restored if you click again. Imported players are copies: editing them does not change the source.",
            "Save the team first: a team with unsaved changes can't open or add players. Creating or importing a player writes it immediately; save each player's edits in their editor, then save the team for removals and relic changes. Changing the template changes which slots show without deleting stored players.",
            "The game uses the saved roster for that team. Fill every slot the template needs before starting a run, except an active skater slot you may leave open for a starting superstar. Campaign squad copies keep their own rosters.",
            "A file in the players folder is not by itself a roster assignment. Incomplete players still need their required fields. Behavior controls and starting relics are separate settings. Two-line and unusual squad combinations need checking in game.", ["players", "behaviors", "squads", "starting"]),
        new("squads", "Custom squads and per-team presets",
            "Open superstar/bench options on the Custom teams card opens Choose campaign team. Each player team has its own template preset. Open the team and use Squad behaviors to override its gameplay rules and starting screens independently. Click a player team to edit it, Add player team to create one, or Import player team from library to copy a saved team in. Use player teams makes the campaign's teams playable; Custom teams only hides the base-game squads. Superstar selection and Bench draft can be enabled on any team. An explicitly empty selected pool skips its screen.",
            "Save campaign keeps campaign switches and starting pools. Opening or adding a team saves the campaign's working changes first. Saving a player's Squad template changes only that team. Explicit On / Off overrides stay unchanged when its preset changes. Turning Use player teams off keeps the teams and their selected pools.",
            "Enabled player teams appear on the Custom Squads page of the game's squad select, alongside the base-game squads unless Custom teams only is on. Setup follows each team's preset and explicit behavior overrides. A game-version mismatch alone does not block custom squads. Native overrides that need verified hooks may remain unavailable until compatibility is updated.",
            "Check the starting flow, mascot and card presentation, large lists and controller selection in game. The Squad behaviors guide lists each control and the presets that enable it by default.", ["behaviors", "starting", "maps", "rosters"]),
        new("behaviors", "Squad behaviors · presets and overrides",
            "Each player team starts from its own native template preset. In the Squad behaviors tab, Inherit follows that preset's default; On and Off override a rule for this team. Explicit overrides survive a preset change. Template default and Effective show what will run. Search filters the controls without changing them. The reference below explains every control and lists which presets enable it by default. Starting relic effects are separate: in Team roster, Add template starting relics copies the base-team relics into the editable list without duplicates. Remove any relic effect you do not want.",
            "Save player team keeps the preset, overrides, active starters and relic list. Conflicting rules and unmet dependencies block saving and explain what must change. With a three- or four-skater limit, choose Start active on the desired roster cards; other authored players remain on the bench. Campaign reward pools must also meet their whole-route reserve, including enabled squad rules and starting rewards.",
            "The runtime routes the audited player-squad checks through the selected team's effective settings, preserving its custom identity. Superstar selection and Bench draft control their screens independently; an explicitly empty selected pool skips its screen. GM match reward mix On uses the native GM reward counts, while Off uses the node's saved counts; bonus relics still apply. Restart the game after saving and start a new run to test roster and starting-screen changes. Studio does not clear existing run progress.",
            "Save validation catches known dependencies and conflicts; it does not simulate a playthrough or prove every possible combination. With No Effects, later bench recruitment requires Bench draft On and Bench Size above zero; an explicitly empty starting pool skips the draft without removing that capacity. Existing runs keep their saved bench and roster. Check representative starting, match and Continue behavior for the settings you changed.", ["squads", "rosters", "starting", "rewards", "nodes"]),
        new("starting", "Starting bench and superstar choices",
            "Ordinary campaigns show nine bench cards and three superstar cards; copied vanilla campaigns instead show checked candidate lists that retain native identities. Each team's screen controls decide when its pools are used. For the bench, Use base-game bench switches between the game's own nine and your custom cards; only the visible set is used. Superstar cards are always custom players. Bulk import players opens a searchable checkbox list with Player library, Base game, In-game custom and Campaign custom sources. Selections stay checked when you switch sources or search. One shared limit counts the empty slots; filled cards are preserved. Save campaign keeps the new slot choices. Create or import a player into a card, open it to edit, or Remove to clear it; new players start from your default look. Selected pools are kept when a team stops using them.",
            "Both pools are on the Choose campaign team page, below the player-team list; Save campaign keeps them. Creating or importing a choice writes its player file immediately, and opening one saves the campaign's working changes first.",
            PoolChoiceGuidance.Bench + " " + PoolChoiceGuidance.Superstars,
            "A kept hidden pool is not necessarily active. Base-game bench players are read from your game; check them after game updates.", ["squads", "players", "sources"]),
        new("opponents", "Opponent behavior and match settings",
            "Opponent settings sets the offensive and defensive formations, Puck / ball, Playing surface, Tycoons two-line behavior and individual special effects. Effects stack unless they conflict; a conflicting alternative stays disabled until the current one is unchecked. A team saved with an older team type shows it until you edit an effect. Roster players have role-specific talents and abilities. A team only plays where you assign it: on a map node, or with Assign to a match node on the Opponents list.",
            "Save opponent keeps the team's behavior and presentation. Save each player after editing their stats or talents. Assignments made on the map or the Opponents list are kept by Save maps or Save campaign. × on the Opponents list removes a team from the campaign and keeps a copy in _removed_opponents.",
            "The mod applies these settings when you play that opponent. Each effect's explanation lists its required node type, equipped ability, player identity or gameplay trigger. Enabling an effect does not equip its ability or bypass those requirements. Native-copy opponents also apply whenever native selection chooses that team. Formations, effects and match presentation happen in the match; the Studio does not simulate them.",
            "Not every player ability works for AI opponents, and goalies have no ability. Two-line behavior needs all five Line 2 positions filled. Brawl offers still use the game's challenge gates. Copy vanilla campaign retains native identities needed by identity-specific effects; ordinary imports do not. Copied Golfers retain all 13 native skaters, including reserves, while the editor exposes five or ten roster slots. A new custom roster does not gain those reserve or transformation identities from its name or outfit. Check AI decisions, effect timing and puck and surface appearance in real matches.", ["maps", "rosters", "players"]),
        new("maps", "Maps · documents, node builder and game preview",
            "Map tabs are the campaign's maps in play order; + Add map adds one and × on a tab removes it. Map look picks the act artwork. Import base-game map replaces the selected map with a base-game layout or a map from another campaign, whose team assignments are cleared. In Node builder each layer holds up to two nodes, separated for native map artwork. + Insert layer adds a layer, Connect links a node to the next layer and Disconnect cuts its incoming paths. The first layer and the Boss keep their horizontal position. Game preview estimates native placement. Undo and Redo step through edits; Fit and zoom change the view. Fit node placement repairs supported coordinates in the draft. Older layers with more than two nodes must be reduced or redistributed before saving; no nodes or routes are silently removed.",
            "Save maps (Ctrl+S) checks every route and writes the maps; Save campaign also saves them. The previous layouts are backed up. A route problem must be fixed before saving. Node changes go into the map draft right away, and nothing reaches disk until you save.",
            "Saved maps apply to new runs. A node with a campaign team plays that team; match nodes left empty use the game's own opponents. Build a connected route through the encounters to the final Boss and check it with the campaign's squad template.",
            "Game preview is an editor projection, not a run. Maps still following the template can change when the template changes; saved maps keep their own layout. Check route generation, node selection and boss transitions in game.", ["nodes", "opponents", "campaign"]),
        new("nodes", "Node settings, rewards and random events",
            "Click a node to open its settings. Node type changes what the node is; the Boss can't be changed or removed, and Remove node deletes any other node. Match and Boss nodes take a team and a stadium. Match, Boss and Challenge nodes have Periods and Period length controls, each defaulting to Use base-game setting. Overrides apply to timed matches; goal-target rules stay unchanged. Match nodes set talent and relic reward counts: " + PoolChoiceGuidance.MatchRewards + " General Manager nodes set how many players to recruit, and Random event nodes have Random event options with relative event weights.",
            "Node settings go into the map draft as you change them; Done closes the dialog and Undo reverts. Random event weights have their own Apply and Cancel. Save maps writes everything after checking routes.",
            "The mod reads the saved nodes when it builds the campaign route. The stadium sets the node's art on the world map; the match arena comes from the opponent. Random event weights choose 1 event per node from 5 types. Zero excludes an event, and positive weights set relative odds. Save maps applies them to newly generated maps; existing map events stay the same.",
            "Saved custom random pools override native placement restrictions: connected nodes and nodes in one layer can repeat, Nurse can appear before a match, and Solo Squad can roll multiple Blademasters. Template replacements preserve these custom choices. Unedited random nodes keep native behavior. Looking at a route in the editor is not proof of every transition in game.", ["maps", "rewards", "agents"]),
        new("agents", "Free agents and recruitment",
            "Check the base-game and custom players who can be recruited. Unchecked custom players stay available through Edit player. Custom has Import and Make New for campaign-only free agents; both add a checked player. Bulk import players adds checked skaters from Player library, Base game, In-game custom and Campaign custom in one batch, with search and Select shown and no starting-slot limit. Source originals stay unchanged. Existing campaign player names must be unique; an import error leaves the checklist open and adds no players. The General Manager template needs General Manager nodes on the maps to offer recruits. The free-agent pool is separate from a team's roster and starting bench.",
            "Save campaign keeps both lists' selections. Import and Make New ask you to save pending campaign changes first and write the player immediately; save their edits in the player editor. The game's default free agents are used only when no player is checked in either list.",
            "Players in the pool become recruitment candidates at the right events, and a small pool repeats players to fill each offer. Adding a free agent does not make them a starter or guarantee they appear in the next offer.",
            "The separate Free-agent talent pool controls random extras on new recruits and General Manager contracts. Checkboxes select exact talent levels: unchecked levels cannot roll directly or appear through an upgrade, including random talent lists in imported recruit templates. Fixed player talents stay intact. Base-game defaults include native base and upgrade levels. Edited pools can roll checked higher levels directly; checked native base talents retain upgrade chances only into checked levels. Multipliers change direct-roll weights, while Regular and Chaos rewards remain independent. Weight zero blocks direct rolls; unchecking also blocks upgrade outcomes. No checked talent means no random extras, while no checked recruitable player uses the native player pool. Existing generated offers, signed players and contracts keep their saved choices. Check offers and recruited players' looks in game.", ["starting", "nodes", "players"]),
        new("rewards", "Reward pools · categories and eligibility",
            "Choose a tab: relics, regular talents, goalie talents, abilities or Chaos talents. Base game pool uses native eligibility; the wizard's Chaos pool uses the game's Chaos category independently of regular talents. Turn Base game pool off to draw random rewards only from checked entries. Include Chaos talents in Regular talents and Include regular talents in Chaos expand only that tab's selectable catalog. " + PoolChoiceGuidance.CatalogExpansion + " Search filters the list. Unresolved imported titles remain visible as unavailable entries.",
            "Save campaign writes each pool's independent reward choices and catalog preference, and blocks an undersized custom pool. The minimum follows the longest route plus two spare choices, accounting for starting powers and eligible families. Switching to Base game retains your custom selections and catalog preferences for later.",
            "The mod refreshes saved reward choices before the next random reward roll. Base and upgraded entries follow their own checkboxes for random rewards. Explicit upgrades of an owned talent, ability or relic follow the game's upgrade rules separately. Fixed node rewards and random reward pools are separate settings.",
            "Normal relic and skater-talent offers each have 3 choices; goalie-talent events also offer 3. Fan #1 can mix stat, size, talent and ability choices, showing up to 3; a single ability node rolls 1. The wizard offers up to 2 Chaos talents. " + PoolChoiceGuidance.RewardEligibility + " Unavailable imported titles may not resolve in the current game.", ["nodes", "players", "sources"]),
        new("audio", "Goal sounds and audio import",
            "Goal celebration in Team settings: Choose audio file converts a clip into the team's goal sound, Preview and Stop play it, and the slider sets its volume. Use base game sound goes back to the default. Help and this guide never play sound.",
            "Choosing a file converts it into the editor draft using temporary files; Save player team or Save opponent embeds the audio, file name and volume in the team. Preview makes a temporary WAV that Stop or leaving the page cleans up. Use base game sound clears the draft choice; save to keep that.",
            "The mod plays the team's goal sound instead of the game's when that team scores, at the chosen volume together with the game's master and effects volume. Supported team exports carry the audio.",
            "Every clip is converted with the bundled FFmpeg, or FFmpeg on your PATH. Files up to 256 MB are accepted and clips are limited to 60 seconds. Preview works on Windows. A successful import does not prove in-game timing or volume.", ["teams", "export"]),
        new("heads", "Head Editor · PNG projects and helmet artwork",
            "Read game artwork on Home first. Head Editor opens a setup dialog before showing previews. Name the head, choose Use a native template or From scratch, then select a native skater head or fitted variant as its layout. Save head and show previews creates and saves the named project first. From scratch creates blank 512 × 512 PNGs for every direction, extra layer and portrait while keeping the selected layout's size, native outlines and collar guides. Open saved head reopens an existing project; Cancel creates no files and stays on the current page. New head opens the same setup dialog from the preview page. Each native template includes its original size, all directions and any extra layers. The eight collar examples show original placement at the same scale across templates; each card shows the source pixel size and native attachment size. Editable PNGs use a 512 × 512 transparent canvas. Import PNGs updates the saved head currently open; recognized direction names include Front, Back, Left, Right, Back left, Back right, Front left, Front right, Alternate back and Portrait. Any size is fitted. Importing Front without Portrait also replaces the portrait with Front, preserving a .bak copy. Replace PNG takes an exact 512 × 512 image. Show native outline overlays the original head silhouette, including its neck edge, at the correct canvas position. The guide stays fixed when you change your artwork. Outline PNG opens it as a separate transparent drawing guide. Refresh PNGs reloads artwork edited in another app. Open project folder, Open outline guides and Open attachment data open the files behind the head.",
            "Save head and show previews saves the project before navigating to its previews. Importing PNGs, replacing a PNG and changing the helmet settings save right away and keep a .bak copy of replaced images. Save rewrites the project file; it does not hold back other changes. Images you edit in another app are saved by that app.",
            "Add to player head options checks the head and adds it to Player > Head. Heads made here already live in your content folder; a head opened from elsewhere is copied in. Return Home and reopen the player editor to see it. Restart the game after installing or changing artwork; the mod must be installed, and a PNG on its own is not enough.",
            "The game preserves the selected native attachment geometry and fits visible replacement pixels to its original size and position, ignoring transparent padding. Native templates have nine or seventeen head attachments: eight directions and an alternate back, with some heads adding a top layer. Images may be shared or mirrored; edit every required card. Matching helmet variants keep their fitted artwork separately, while the game supplies the helmet itself. Reference examples show original artwork and do not update with your edits. Native outlines are drawing guides from the original PNGs; the collar examples show their in-game placement. Check changed directions, layers, animations, helmet fit and the separate portrait in game.", ["appearance", "sources"]),
        new("export", "Export to Play Now · separate game content",
            "Export to Play Now in a player or team editor translates Studio content into the game's own custom-content format. The look is resolved for export, and identities, equipment, logos, goal audio and gameplay choices are translated rather than copied as editor labels. Each export also keeps a copy in your library.",
            "Export checks and reads the current editor fields; it does not save the Studio source. Save a team's equipment and settings before exporting it, and save each roster player. Restart the game to load the export, and export again after later edits.",
            "The game's custom-content menus load exported players and teams. The game's save format can't hold every color, equipment piece, ability and talent, so the mod restores the extras from companion data. Exporting does not assign anything to a campaign.",
            "Play Now teams hold one player each at LW, C, RW, LD, RD and G, so extra lines can't be exported. Export a player who carries relics with their team, and fix random talents first. The game must have been launched once. The mod restores each exported player's resolved number style from companion data. Check identity, home and away kits, logos, talents, relics and abilities in a live match.", ["sources", "appearance", "teams"])
    ];
}
